descShort: {
  en: "An eternal connection between life and superconsciousness, where the flower becomes a symbolic synthesis of humanity; blooming",
  
  bn: "জীবন ও অতিচেতনার এক অনন্ত সংযোগ, মানবতার এক প্রতীকী সংশ্লেষ; মর্নিং গ্লোরি ফুল ভোরের আলোয় প্রস্ফুটিত হওয়ায় এটি",
  
  hi: "जीवन और अतिचेतना के बीच एक शाश्वत सम्बन्ध, जहाँ यह पुष्प मानवता के एक प्रतीकात्मक संश्लेषण के रूप में प्रकट होता है; प्रातःकालीन प्रकाश में",
  
  sa: "जीवनस्य अतिचेतनायाश्च मध्ये एकः शाश्वतः सम्बन्धः, यत्र एतत् पुष्पं मानवतायाः प्रतीकात्मकसंश्लेषरूपेण प्रकटते; प्रातःप्रकाशे प्रस्फुटितत्वात् मॉर्निङ्ग् ग्लोरी",
},

descFull: {
  en: "in the morning light, Morning Glory is a natural symbol of awakening and unfolding; its closed bud gradually opens its petals, indicating the movement from the unconscious toward consciousness; the center of the flower represents a point of concentration, while the petals expanding outward express the multidimensional forms of thought, experience, and imagination; its connection with dawn suggests a new beginning and renewal; thus this symbol guides the mind from stillness toward blossoming, where creativity, insight, and self-knowledge gradually emerge from within silence;",
  
  bn: "জাগরণ ও উন্মোচনের স্বাভাবিক প্রতীক; বন্ধ কুঁড়ি থেকে ধীরে ধীরে বিস্তৃত পাপড়ি অচেতন স্তর থেকে সচেতনতার দিকে উন্মোচনের পথ নির্দেশ করে; ফুলের কেন্দ্র একাগ্রতার বিন্দু, আর চারদিকে বিস্তৃত পাপড়ি চিন্তা, অনুভব ও কল্পনার বহুমাত্রিক প্রকাশ; ভোরের সঙ্গে তার সম্পর্ক নতুন সূচনা ও পুনর্জাগরণের ইঙ্গিত বহন করে; তাই এই প্রতীক মনকে স্থিরতা থেকে প্রস্ফুটনের দিকে নিয়ে যায়, যেখানে নীরবতার ভিতর থেকে সৃজনশীলতা, উপলব্ধি ও আত্ম-জ্ঞান ধীরে ধীরে প্রকাশিত হয়;",
  
  hi: "खिलने के कारण मॉर्निंग ग्लोरी जागरण और उद्घाटन का प्राकृतिक प्रतीक है; बन्द कली से धीरे-धीरे फैलती पंखुड़ियाँ अचेतन स्तर से चेतना की ओर उन्मोचन का मार्ग दर्शाती हैं; पुष्प का केंद्र एकाग्रता का बिन्दु है, जबकि बाहर की ओर विस्तृत पंखुड़ियाँ विचार, अनुभूति और कल्पना के बहुआयामी रूपों को व्यक्त करती हैं; प्रभात से इसका सम्बन्ध नए आरम्भ और पुनर्जागरण का संकेत देता है; इस प्रकार यह प्रतीक मन को स्थिरता से प्रस्फुटन की ओर ले जाता है, जहाँ मौन के भीतर से सृजनशीलता, अन्तर्दृष्टि और आत्मज्ञान धीरे-धीरे प्रकट होते हैं;",
  
  sa: "जागरणस्य उन्मीलनस्य च प्राकृतिकं प्रतीकम्; संवृता कलिका शनैः शनैः पल्लवान् प्रसारयन्ती अचेतनस्तरात् चेतनायाः दिशि उन्मीलनमार्गं निर्दिशति; पुष्पस्य केन्द्रम् एकाग्रतायाः बिन्दुः, बहिर्दिशि प्रसृताः पल्लवाश्च विचारस्य अनुभूतेः कल्पनायाश्च बहुआयामीरूपाणि प्रकाशयन्ति; प्रभातेन सह तस्य सम्बन्धः नूतनारम्भस्य पुनर्जागरणस्य च संकेतं वहति; अतः एतत् प्रतीकं मनः स्थिरतायाः प्रस्फुटनस्य दिशि नयति, यत्र मौनस्य अन्तः सृजनशीलता अन्तर्दृष्टिः आत्मज्ञानं च शनैः शनैः प्रकाशन्ते;",
},
 size: "Oil on canvas, 17'' x 17'' 2000",
