descShort: {
  en: "In the silence of the mother's womb, life moves through its deepest transformation; within the amniotic fluid, the embryo's first",

  bn: "মায়ের গর্ভের নীরবতায় জীবন তার গভীরতম রূপান্তরের মধ্য দিয়ে অগ্রসর হয়; অ্যামনিওটিক তরলের মধ্যে ভ্রূণের প্রথম স্পন্দন, ক্ষুদ্র নড়াচড়া",

  hi: "माँ के गर्भ की नीरवता में जीवन अपने गहनतम रूपान्तरण से होकर आगे बढ़ता है; अम्नियोटिक द्रव में भ्रूण का प्रथम स्पन्दन, सूक्ष्म गतियाँ और अदृश्य",

  sa: "मातुः गर्भस्य मौने जीवनं स्वस्य गहनतमरूपान्तरणेन अग्रे गच्छति; अम्नियोटिकद्रवे भ्रूणस्य प्रथमस्पन्दनं, सूक्ष्मगतयः,",
},

descFull: {
  en: "pulse, subtle movements, and unseen life-force gradually reveal the potential of a complete body; the interwoven arrangement of circles and triangles indicates the organization and expansion of this inner energy; delicate symbols like air bubbles suggest the future relationship between life and breath; this process of becoming visible from the unseen is nature's eternal creation — where every life carries within itself the potential of a new star;",

  bn: "এবং অদৃশ্য জীবনশক্তি ধীরে ধীরে একটি পূর্ণাঙ্গ দেহের সম্ভাবনাকে প্রকাশ করে; বৃত্ত ও ত্রিভুজের পারস্পরিক বিন্যাস সেই অন্তর্গত শক্তির সংগঠন ও বিস্তারকে নির্দেশ করে; বায়ুবুদ্‌বুদের মতো সূক্ষ্ম প্রতীক জীবন ও শ্বাসের ভবিষ্যৎ সম্পর্কের ইঙ্গিত বহন করে; অদৃশ্য থেকে দৃশ্যমান হওয়ার এই প্রক্রিয়া প্রকৃতির চিরন্তন সৃষ্টিচক্র—যেখানে প্রতিটি জীবন নিজের মধ্যে একটি নতুন নক্ষত্রের সম্ভাবনা ধারণ করে;",

  hi: "जीवनशक्ति धीरे-धीरे एक पूर्ण शरीर की सम्भावना को प्रकट करती हैं; वृत्त और त्रिभुजों की परस्पर व्यवस्था उस अन्तर्निहित ऊर्जा के संगठन और विस्तार का संकेत देती है; वायु-बुलबुलों जैसे सूक्ष्म प्रतीक जीवन और श्वास के भावी सम्बन्ध का संकेत देते हैं; अदृश्य से दृश्य होने की यह प्रक्रिया प्रकृति का शाश्वत सृजनचक्र है—जहाँ प्रत्येक जीवन अपने भीतर एक नए नक्षत्र की सम्भावना धारण करता है;",

  sa: "अदृश्यजीवनशक्तिश्च शनैः शनैः पूर्णशरीरस्य सम्भावनां प्रकाशयन्ति; वृत्तत्रिकोणयोः परस्परविन्यासः अन्तर्निहितशक्तेः संगठनं विस्तारं च निर्दिशति; वायुबुद्बुदवत् सूक्ष्मप्रतीकानि जीवनस्य श्वासस्य च भाविसम्बन्धस्य संकेतं वहन्ति; अदृश्यात् दृश्यत्वस्य एषा प्रक्रिया प्रकृतेः शाश्वतसृष्टिचक्रम् — यत्र प्रत्येकं जीवनं स्वान्तरे नूतनतारकस्य सम्भावनां धारयति;",
},

