  hi: "शक्ति पहले एक सूक्ष्म स्पन्दन के रूप में प्रकट हुई थी, वही अब शरीर के प्रत्येक स्तर में जीवन-प्रवाह के रूप में विकसित होती है; श्वास और वायु-बुलबुलों के प्रतीक जीवन की निरन्तर लय को दर्शाते हैं; केंद्र से विस्तृत ज्यामिति उसके ब्रह्माण्डीय विन्यास को प्रकट करती है; प्रत्येक श्वास हमें प्रकृति के सार का स्मरण कराती है — प्रत्येक जीवन अपने प्रकाश में एक नया रूप, एक नया नक्षत्र बन जाता है;",

