  hi: "शून्य-घंटे के मौन बिन्दु से प्रथम श्वास की लय में जीवन का आरम्भ होता है; यहाँ श्वास केवल शरीर की स्वाभाविक क्रिया नहीं, बल्कि जीवन को समय से जोड़ने वाला एक",

