  hi: "३) शून्य-घंटे का प्रवाह — कार्मिक जीवन का प्रत्यावर्तन और ऋषि का प्रतिनिधित्व",
  sa: "३) शून्यघण्टस्य प्रवाहः — कार्मिकजीवनस्य प्रत्यावर्तनं ऋषेः प्रतिनिधित्वं च",
