descShort: {
  en: "In the flow of Zero Hour, life repeatedly returns toward its source through the consequences of its actions; karma here is not",

  bn: "শূন্য-ঘণ্টার প্রবাহে জীবন তার কর্মের প্রতিফলের মধ্য দিয়ে বারবার নিজের উৎসের দিকে প্রত্যাবর্তন করে; কর্ম এখানে শুধু কার্যকলাপ নয়,",

  hi: "शून्य-घंटे के प्रवाह में जीवन अपने कर्मों के परिणामों के माध्यम से बार-बार अपने स्रोत की ओर लौटता है; यहाँ कर्म केवल क्रिया नहीं, बल्कि जीवन के संस्कार,",

  sa: "शून्यघण्टस्य प्रवाहे जीवनं स्वकर्मणां फलानां माध्यमेन पुनः पुनः स्वस्य स्रोतसः प्रति प्रत्यावर्तते; अत्र कर्म केवलं क्रिया न, अपि तु जीवनस्य संस्काराणाम्",
},
 

descFull: {
  en: "merely an activity, but the continuous flow of life's refinement, experience, and their results; every reality and every action creates a new point in the life of the Zero Hour, where the symbol of this return is manifested as the emblem of the life-giver — enabling life to observe itself beyond its outward movement and realize its inner thought; thus Zero Hour becomes a symbol of the unbroken cycle of karma, return, and self-realization;",

  bn: "জীবনের সংস্কার, অভিজ্ঞতা ও তার ফলের ধারাবাহিক প্রবাহ; প্রতিটি বাস্তবতা ও কর্ম শূন্য মুহূর্তের জীবনে একটি নতুন বিন্দু নির্মাণ করে, যেখানে এই প্রত্যাবর্তনের জীবন-দেবতার প্রতীকটি কার্মিক হয়ে ওঠে—যা জীবনকে বাহ্যিক গতির বাইরে থেকে পর্যবেক্ষণ এবং তার অন্তর্গত চিন্তাকে উপলব্ধি করার মাধ্যমে উপলব্ধি করে; শূন্য-ঘণ্টা তাই কর্ম, প্রত্যাবর্তন ও আত্ম-উপলব্ধির এক অবিচ্ছিন্ন চক্রের প্রতীক হয়ে ওঠে;",

  hi: "अनुभव और उनके परिणामों का निरन्तर प्रवाह है; प्रत्येक वास्तविकता और प्रत्येक कर्म शून्य क्षण के जीवन में एक नया बिन्दु निर्मित करता है, जहाँ इस प्रत्यावर्तन का जीवन-देवता का प्रतीक कार्मिक रूप में प्रकट होता है — जो जीवन को बाह्य गति से परे स्वयं का अवलोकन करने और अपने अन्तर्निहित विचार को अनुभव करने में सक्षम बनाता है; अतः शून्य-घंटा कर्म, प्रत्यावर्तन और आत्म-साक्षात्कार के एक अविच्छिन्न चक्र का प्रतीक बन जाता है;",

  sa: "अनुभवानां तेषां फलानां च निरन्तरः प्रवाहः; प्रत्येकं वास्तविकत्वं प्रत्येकं कर्म च शून्यक्षणस्य जीवने एकं नूतनं बिन्दुं निर्माति, यत्र अस्य प्रत्यावर्तनस्य जीवनदेवतायाः प्रतीकं कार्मिकरूपेण प्रकाशते — यत् जीवनं बाह्यगतेः परे स्वयम् अवलोकयितुं स्वस्य अन्तर्निहितं चिन्तनम् अनुभावयितुं च समर्थं करोति; अतः शून्यघण्टा कर्मणः प्रत्यावर्तनस्य आत्मोपलब्धेश्च अविच्छिन्नस्य चक्रस्य प्रतीकं भवति;",
},

