   "यह प्रोसेस नेचर के सेल्फ-रेगुलेटिंग साइकिल को दिखाता है, जहां गर्मी भाप में बदल जाती है, एटमॉस्फियर में ऊपर उठती है, और बारिश के रूप में वापस आती है; यह साइकिल जीवन और नेचर के बीच तालमेल बनाए रखता है; इसके ज़रिए, चेतना का बनना एक अंदरूनी इवोल्यूशन का हिस्सा बन जाता है—जहां मेडिटेशन वाला विचार बायोकॉन्शसनेस यानी अंदरूनी दुनिया के डेवलपमेंट में एक तरह के बायोडेवलपमेंट का काम करता है;",
