descFull: {
  en: "existence, where the discipline of consciousness restores the continuity of life through nature's rhythm; here, breath, pulsation, and inner force become interconnected, creating an organized flow of life; even amid nature's constant changes, this discipline keeps life grounded in its own balance; when consciousness recognizes the laws of nature, life becomes not merely an expression of existence, but a conscious process of preservation, harmony, and renewal;",

  bn: "ছন্দের সঙ্গে চেতনার শৃঙ্খলা জীবনের ধারাবাহিকতাকে প্রতিস্থাপন করে; এখানে শ্বাস, স্পন্দন ও অন্তর্গত শক্তি পরস্পরের সঙ্গে যুক্ত হয়ে জীবনের একটি সুসংগঠিত প্রবাহ সৃষ্টি করে; প্রকৃতির পরিবর্তনশীলতার মধ্যেও এই শৃঙ্খলা জীবনকে তার নিজস্ব ভারসাম্যে স্থিত রাখে; চেতনা যখন প্রকৃতির নিয়মকে উপলব্ধি করে, তখন জীবন কেবল অস্তিত্বের প্রকাশ নয়—বরং সংরক্ষণ, সামঞ্জস্য ও পুনর্নবীকরণের এক সচেতন প্রক্রিয়ায় পরিণত হয়;",

  hi: "जहाँ प्रकृति की लय के साथ चेतना का अनुशासन जीवन की निरन्तरता को पुनर्स्थापित करता है; यहाँ श्वास, स्पन्दन और अन्तर्निहित शक्ति परस्पर जुड़कर जीवन का एक सुव्यवस्थित प्रवाह निर्मित करते हैं; प्रकृति के निरन्तर परिवर्तन के मध्य भी यह अनुशासन जीवन को उसके अपने संतुलन में स्थिर रखता है; जब चेतना प्रकृति के नियमों को समझती है, तब जीवन केवल अस्तित्व की अभिव्यक्ति नहीं रहता, बल्कि संरक्षण, सामंजस्य और नवीनीकरण की एक सचेत प्रक्रिया में परिवर्तित हो जाता है;",

  sa: "प्रकृतेः लयेन सह चेतनायाः अनुशासनं जीवनस्य सातत्यं पुनः स्थापयति; अत्र श्वासः स्पन्दनम् अन्तर्निहितशक्तिश्च परस्परं सम्बद्धाः भूत्वा जीवनस्य सुव्यवस्थितं प्रवाहं निर्मान्ति; प्रकृतेः सततपरिवर्तनस्य मध्येऽपि एतदनुशासनं जीवनं स्वकीये सन्तुलने स्थिरं धारयति; यदा चेतना प्रकृतेः नियमाञ् अवगच्छति, तदा जीवनं केवलमस्तित्वस्य प्रकाशनं न भवति, अपि तु संरक्षणस्य सामञ्जस्यस्य नवीनीकरणस्य च सचेतनप्रक्रियायां परिणमति;",
},

