      "प्रकृतेः अपवर्तनमाध्यमेन मानवचेतनायाः उद्भवः भवति, यत्र सूर्येण सौरमण्डलं स्थिरं भवति तथा पृथिव्याः जीवनचक्रस्य ज्वारभाटयोः मध्ये निहितं भवति; प्रकृतेः नियमेषु ग्रहणानि निरन्तरं नूतनानि रूपाणि धारयन्ति, यत्र संस्कृतेः छाया तथा अचेतनमनसः जीवनसिद्धान्ताः अथवा स्वप्नानि पुनः प्रतिष्ठापितानि भूत्वा अनुनादितानि भवन्ति;",
