  hi: "शून्यता की श्वास और अन्तर्निहित मौन में जीवसत्ता की हृदयस्पन्दन परम सत्ता के साथ एक सूक्ष्म सम्बन्ध स्थापित करती है, जहाँ प्रकृति और जीवन-संस्कृति का",

