  hi: "शून्यता के मौन विस्तार में सूक्ष्मतम स्पन्दन भी एक गहन अनुनाद में परिवर्तित हो जाता है; एक सूक्ष्म बिन्दु के समान आदिम जीवन-स्पन्दन धीरे-धीरे विस्तृत होकर",

