descShort: {
  en: "In the silent expanse of emptiness, a life of natural meditation, awareness, and consciousness is liberated from the darkness or",

  bn: "শূন্যতার নীরব পরিসরে প্রাকৃতিক ধ্যান, সাধনা ও সচেতনতার জীবন, যা সত্তার সঙ্গে প্রকৃতির অন্ধকার বা জীবনের দৈন্যতা থেকে মুক্তি দেয়",

  hi: "शून्यता के मौन विस्तार में प्राकृतिक ध्यान, साधना और चेतना का जीवन, जो सत्ता को प्रकृति के अन्धकार अथवा जीवन की दैन्यता से मुक्त करता है और प्रकाश",

  sa: "शून्यतायाः मौने विस्तारे प्राकृतिकध्यानस्य साधनायाश्च चेतनायाश्च जीवनं, यत् सत्तां प्रकृतेः अन्धकारात् जीवनस्य दैन्यात् च विमोचयति, प्रकाशस्य सत्यस्य च",
},
 
descFull: {
  en: "impoverishment of life and establishes a profound connection with the radiance of light and truth; when the mind withdraws from external noise and becomes still, the subtle rhythm of nature, the flow of life, and the inner pulsation continue to be experienced; this stability is not passivity, but an awakened state of self-awareness, where silence itself becomes a language of expression; this connection among meditation, nature, and culture gives human life birth to a peaceful, restrained, and deeply inward life-consciousness;",

  bn: "এবং আলো বা সততার রূপায়ণের সঙ্গে এক গভীর সংযোগ স্থাপন করে; বাহ্যিক কোলাহল থেকে সরে এসে মন যখন স্থির হয়, তখন প্রকৃতির সূক্ষ্ম ছন্দ, জীবনপ্রবাহ ও অন্তর্গত স্পন্দন অনুভূত হতে থাকে; এই স্থিতিশীলতা নিষ্ক্রিয়তা নয়, বরং আত্মসচেতনতার এক সজাগ অবস্থা, যেখানে নীরবতা নিজেই প্রকাশের ভাষা হয়ে ওঠে; ধ্যান, প্রকৃতি ও সংস্কৃতির এই সংযোগ মানবজীবনে এক শান্ত, সংযত ও অন্তর্মুখী জীবনবোধের জন্ম দেয়;",

  hi: "तथा सत्य के रूपान्तरण के साथ एक गहरा सम्बन्ध स्थापित करता है; बाहरी कोलाहल से हटकर जब मन स्थिर होता है, तब प्रकृति की सूक्ष्म लय, जीवन-प्रवाह और अन्तर्निहित स्पन्दन का अनुभव बना रहता है; यह स्थिरता निष्क्रियता नहीं, बल्कि आत्मचेतना की एक जाग्रत अवस्था है, जहाँ मौन स्वयं अभिव्यक्ति की भाषा बन जाता है; ध्यान, प्रकृति और संस्कृति का यह सम्बन्ध मानवजीवन में एक शान्त, संयमित और गहन अन्तर्मुखी जीवनबोध को जन्म देता है;",

  sa: "रूपान्तरणेन सह गम्भीरं सम्बन्धं स्थापयति; बाह्यकोलाहलात् निवृत्त्य मनसि स्थिरे जाते प्रकृतेः सूक्ष्मलयः, जीवनप्रवाहः अन्तःस्पन्दनं च अनुभूयते; एषा स्थिरता निष्क्रियता न, अपि तु आत्मचेतनायाः जाग्रदवस्था, यत्र मौनमेव अभिव्यक्तेः भाषा भवति; ध्यानस्य प्रकृतेः संस्कृतेश्च अयं संयोगः मानवजीवने शान्तं संयतं गहनान्तर्मुखं च जीवनबोधं जनयति;",
},

