   hi: "विशाल ब्रह्माण्ड में जगत का उद्भव सृष्टि का आरम्भ है, जो स्वयं जीवन का प्रतिबिम्ब और एक अव्यक्त रहस्य है—एक दूरस्थ अतीत, जब जीवन मौन था, किन्तु सम्भावनाओं से परिपूर्ण था; स्वप्न और कल्पनाप्रेरित विचार अतीत के पुनर्मूल्यांकन तथा भविष्य से आने वाले संदेशों में",

   sa: "विशाले ब्रह्माण्डे जगतः उद्भवः सृष्टेः आरम्भः, यः स्वयं जीवनस्य प्रतिबिम्बम् अव्यक्तं रहस्यं च—दूरस्थः अतीतः, यदा जीवनं मौनम् आसीत्, तथापि सम्भावनापूर्णम्; स्वप्नानि कल्पनाप्रेरिताश्च विचाराः अतीतस्य पुनर्मूल्याङ्कनरूपेण भविष्यतः आगच्छद्भिः सन्देशैश्च परिणमन्ति; जीवनस्य अन्वेषणम्",
