   "जीवनस्य प्रत्येकं तरङ्गं सूक्ष्मतया सत्तां प्रभावितं करोति, एवं जीवनं रहस्यमयस्य संक्रमणस्य दिशि विकसितं भवति, यत्र लौकिकम् आध्यात्मिकं च शाश्वते प्रतिबिम्बे एकीभवतः; जीवनस्य प्रत्येकः क्षणः चेतनया जीवनम् अग्रे नयति, यत्र सत्तायाः प्रतिक्रिया सत्तायाः एव प्रतिबिम्बं भवति;",
 
