descShort: {
  en: "Here, solitude signifies a conscious practice that brings together temporary withdrawal, worldly existence, and the contemplative life, through which the",

  bn: "এখানে একাকিত্ব বলতে সাময়িক বিচ্ছিন্নতা, জাগতিক ও সন্ন্যাসী জীবনের সংমিশ্রণ, যেখানে জীবন-অস্তিত্বের সারসত্তা রূপান্তরিত হয় এবং আধ্যাত্মিকতা পরিচালিত",

  hi: "यहाँ एकांत का अर्थ अस्थायी विरक्ति, सांसारिक और संन्यासी जीवन के समन्वय से है, जहाँ जीवन-अस्तित्व का सार रूपांतरित होता है और आध्यात्मिकता द्वारा निर्देशित होता है; जैसे गर्भाशय सृष्टि की",

  sa: "अत्र एकान्तः तु सामयिकविरक्तिः, लौकिकसंन्यासिजीवनयोः समन्वयश्च, यत्र जीवनसत्त्वस्य सारं रूपान्तरितं भवति आध्यात्मिकतया च नीयते; यथा गर्भाशयः सृष्टेः आदिमप्रकृतिं धारयति, तथा",
},
 
descFull: {
  en: "essence of being is transformed and guided toward spirituality; just as the womb holds the primordial nature of creation, solitude becomes a conscious return into the inner self, where the mind, withdrawing from the noise of the outside world, becomes absorbed in its own depths and opens the path of self-discovery; through this inward journey, self-reflection gradually transforms into self-realization, transcending the limits of external identity and revealing the deeper meaning of one's inherent consciousness, strength, and existence;",

  bn: "হয়; যেমন গর্ভাশয় সৃষ্টির আদিম প্রকৃতিকে ধারণ করে, তেমনি নির্জনতা হলো নিজের অন্তরাত্মায় ফিরে যাওয়ার এক সচেতন সাধনা, যেখানে মন যখন বাইরের কোলাহল থেকে নিজেকে গুটিয়ে নিয়ে তার গভীরে নিমগ্ন হয়, তখন আত্ম-আবিষ্কারের পথ উন্মুক্ত হয়; এই অন্তর্মুখী যাত্রায় আত্মদর্শন ধীরে ধীরে আত্ম-উপলব্ধিতে রূপান্তরিত হয়, যেখানে বাহ্যিক পরিচয়ের সীমা অতিক্রম করে নিজের অন্তর্নিহিত চেতনা, শক্তি ও অস্তিত্বের গভীরতার অর্থ অনুভূত হয়;",

  hi: "आदिम प्रकृति को धारण करता है, वैसे ही एकांत अपने अंतर्मन में लौटने की एक सचेत साधना बन जाता है, जहाँ मन बाहरी कोलाहल से स्वयं को समेटकर अपनी गहराइयों में निमग्न होता है और आत्म-अन्वेषण का मार्ग खुलता है; इस अंतर्मुखी यात्रा में आत्म-दर्शन धीरे-धीरे आत्म-उपलब्धि में रूपांतरित होता है, जहाँ बाहरी पहचान की सीमाओं को पार कर अंतर्निहित चेतना, शक्ति और अस्तित्व की गहनता का अर्थ अनुभव होता है;",

  sa: "एकान्तः स्वस्य अन्तर्मनसि प्रत्यागमनस्य सचेतनसाधना भवति, यत्र मनः बाह्यकोलाहलात् स्वं संहृत्य स्वगभीरे निमज्जति, आत्मान्वेषणस्य च मार्गः उद्घाट्यते; अस्याम् अन्तर्मुखयात्रायां आत्मदर्शनं शनैः शनैरात्मोपलब्धौ रूपान्तरितं भवति, यत्र बाह्यपरिचयस्य सीमामतिक्रम्य स्वान्तर्निहितचेतनायाः शक्तेः अस्तित्वस्य च गभीरार्थः अनुभूयते;",
},

