title: {
  en: "4) The Reflection of Zero in Emptiness — Insight Through the Reflection of Emptiness",
  bn: "৪) শূন্যতায় শূন্যের প্রতিচ্ছবি — শূন্যতার প্রতিফলনে অন্তর্দৃষ্টি",
  hi: "४) शून्यता में शून्य का प्रतिबिम्ब — शून्यता के प्रतिबिम्ब में अंतर्दृष्टि",
  sa: "४) शून्यतायां शून्यस्य प्रतिबिम्बः — शून्यतायाः प्रतिबिम्बे अन्तर्दृष्टिः",
},

descShort: {
  en: "The reflection of zero within emptiness points to a profound space of inner possibility beyond external absence, where visible forms gradually become still and the",

  bn: "শূন্যতার মধ্যে শূন্যের প্রতিচ্ছবি বাহ্যিক অনুপস্থিতি থেকে অন্তর্নিহিত সম্ভাবনার এক গভীর পরিসরকে নির্দেশ করে, যেখানে দৃশ্যমান রূপ ক্রমে স্থিমিত হয়ে অন্তর্দৃষ্টির সূক্ষ্ম প্রকাশ স্পষ্ট",

  hi: "शून्यता के भीतर शून्य का प्रतिबिम्ब बाहरी अनुपस्थिति से परे अंतर्निहित संभावना के एक गहन क्षेत्र को दर्शाता है, जहाँ दृश्य रूप धीरे-धीरे स्थिर होकर अंतर्दृष्टि की सूक्ष्म अभिव्यक्ति को स्पष्ट करते हैं;",

  sa: "शून्यतायां शून्यस्य प्रतिबिम्बं बाह्याभावात् परे अन्तर्निहितसम्भावनायाः गभीरं क्षेत्रं निर्दिशति, यत्र दृश्यरूपं शनैः शनैः स्थिरीभूय अन्तर्दृष्टेः सूक्ष्मप्रकाशं स्पष्टं करोति; शून्यता मनः अनावश्यकधारणाभ्यः",
},  

 
descFull: {
  en: "subtle expression of insight emerges clearly; emptiness frees the mind from unnecessary concepts, desires, and worldly distractions, allowing a return to its own depths; in that silent reflection, one begins to perceive existence anew, learning to observe thought, feeling, desire, and being with impartial awareness; thus, emptiness is no longer a vacant space—it becomes a profound field of self-reflection, expanding consciousness, and realizing the inner truth;",

  bn: "শূন্যতার মধ্যে শূন্যের প্রতিচ্ছবি বাহ্যিক অনুপস্থিতি থেকে অন্তর্নিহিত সম্ভাবনার এক গভীর পরিসরকে নির্দেশ করে, যেখানে দৃশ্যমান রূপ ক্রমে স্থিমিত হয়ে অন্তর্দৃষ্টির সূক্ষ্ম প্রকাশ স্পষ্ট হয়ে ওঠে; শূন্যতা মনকে অপ্রয়োজনীয় ধারণা, আকাঙ্ক্ষা ও জাগতিক ব্যস্ততা থেকে মুক্ত করে নিজের গভীরে প্রত্যাবর্তনের সুযোগ দেয়; সেই নীরব প্রতিফলনে ব্যক্তি নিজের অস্তিত্বকে নতুনভাবে উপলব্ধি করে, যেখানে চিন্তা, অনুভব, ইচ্ছা ও অস্তিত্বকে নিরপেক্ষভাবে পর্যবেক্ষণের মধ্য দিয়ে ব্যক্তি নিজের প্রকৃত সত্তার মুখোমুখি হতে শেখে; ফলে শূন্যতা আর কোনো শূন্যস্থান থাকে না—তা হয়ে ওঠে আত্মদর্শন, চেতনার প্রসার এবং অন্তর্গত সত্য উপলব্ধির এক গভীর ক্ষেত্র;",

  hi: "शून्यता मन को अनावश्यक धारणाओं, आकांक्षाओं और सांसारिक व्यस्तताओं से मुक्त कर अपनी गहराइयों में लौटने का अवसर देती है; उस मौन प्रतिबिम्ब में व्यक्ति अपने अस्तित्व को नए रूप में अनुभव करता है और विचार, अनुभूति, इच्छा तथा अस्तित्व को निष्पक्ष दृष्टि से देखने के माध्यम से अपनी वास्तविक सत्ता के सम्मुख होना सीखता है; इस प्रकार शून्यता अब कोई रिक्त स्थान नहीं रहती—वह आत्म-दर्शन, चेतना के विस्तार और अंतर्निहित सत्य की अनुभूति का एक गहन क्षेत्र बन जाती है;",

  sa: "शून्यतायां शून्यस्य प्रतिबिम्बं बाह्याभावात् परे अन्तर्निहितसम्भावनायाः गभीरं क्षेत्रं निर्दिशति, यत्र दृश्यरूपं शनैः शनैः स्थिरीभूय अन्तर्दृष्टेः सूक्ष्मप्रकाशं स्पष्टं करोति; शून्यता मनः अनावश्यकधारणाभ्यः आकाङ्क्षाभ्यः लौकिकव्यस्तताभ्यश्च विमोच्य स्वगभीरे प्रत्यागमनस्य अवसरं ददाति; तस्मिन् मौनप्रतिबिम्बे व्यक्तिः स्वस्य अस्तित्वं नूतनतया अनुभूय चिन्तनम् अनुभूतिम् इच्छाम् अस्तित्वं च निरपेक्षदृष्ट्या निरीक्षितुं स्वस्य वास्तविकसत्तायाः सम्मुखं भवितुं च शिक्षते; एवं शून्यता न केवलं रिक्तस्थानं भवति—सा आत्मदर्शनस्य चेतनाविस्तारस्य अन्तर्निहितसत्यस्य च अनुभूतेः गभीरं क्षेत्रं भवति;",
},

