title: {
  en: "3) The Rebirth of Creation through the Rain Cycle — The Transformation of Sound and Reflection",
  bn: "৩) বৃষ্টিচক্রে সৃষ্টির পুনরুত্থান — ধ্বনি ও প্রতিধ্বনির রূপান্তর",
  hi: "३) वर्षाचक्र में सृष्टि का पुनरुत्थान — ध्वनि और प्रतिध्वनि का रूपांतरण",
  sa: "३) वर्षाचक्रे सृष्टेः पुनरुत्थानम् — ध्वनेः प्रतिध्वनेश्च रूपान्तरणम्",
},

descShort: {
  en: "The rebirth of creation through the rain cycle is a symbol of nature’s continuous transformation and renewal, where the mutual ",

  bn: "বৃষ্টিচক্রে সৃষ্টির পুনরুত্থান প্রকৃতির অন্তহীন রূপান্তর ও পুনর্জন্মের প্রতীক, যেখানে চেতনার সূক্ষ্ম শরীর বা সত্তা—বাষ্প, মেঘ, বৃষ্টি ও মাটির",

  hi: "वर्षाचक्र में सृष्टि का पुनरुत्थान प्रकृति के अनंत रूपांतरण और पुनर्जन्म का प्रतीक है, जहाँ चेतना का सूक्ष्म शरीर या सत्ता—वाष्प, मेघ, वर्षा और पृथ्वी—का",

  sa: "वर्षाचक्रे सृष्टेः पुनरुत्थानं प्रकृतेः अनन्तरूपान्तरणस्य पुनर्जन्मनश्च प्रतीकम्, यत्र चेतनायाः सूक्ष्मशरीरस्य वा सत्तायाः—वाष्पस्य मेघस्य वर्षायाः पृथिव्याश्च—पारस्परिकसम्बन्धः जीवनं पुनः सजीवयति; वर्षायाः",
},

descFull: {
  en: "relationship of consciousness with the subtle body or being—vapor, cloud, rain, and earth—reorganizes life anew; the sound of rain expresses the inherent vibration of nature, while its reflection creates new experience within human consciousness; from sound emerges reflection, from reflection realization, and from realization creativity—through this continuous transformation, nature and life are renewed in an eternal rhythm; radiant light emerges amid darkness, where dream and eternal truth become united;",


  bn: "সম্পর্ক জীবনকে পুনরায় সজ্জীবিত করে; বৃষ্টির ধ্বনি প্রকৃতির অন্তর্গত স্পন্দনকে প্রকাশ করে, আর তার প্রতিধ্বনি মানব চেতনায় নতুন অনুভব সৃষ্টি করে; ধ্বনি থেকে প্রতিধ্বনি, প্রতিধ্বনি থেকে উপলব্ধি এবং উপলব্ধি থেকে সৃষ্টিশীলতা—এই ধারাবাহিক রূপান্তরের মধ্য দিয়ে প্রকৃতি ও জীবন এক অবিরাম ছন্দে পুনরুজ্জীবিত হয়; জ্ঞানদীপ্তি বা উজ্জ্বল আলো অন্ধকারের মাঝে প্রকাশিত হয়, যেখানে স্বপ্ন ও শাশ্বত সত্য একত্রিত হয়;",

  hi: "पारस्परिक संबंध जीवन को पुनः सजीव करता है; वर्षा की ध्वनि प्रकृति के अंतर्निहित स्पंदन को अभिव्यक्त करती है, जबकि उसकी प्रतिध्वनि मानव चेतना में नए अनुभव का सृजन करती है; ध्वनि से प्रतिध्वनि, प्रतिध्वनि से अनुभूति और अनुभूति से सृजनशीलता—इस सतत रूपांतरण के माध्यम से प्रकृति और जीवन एक अनवरत लय में पुनर्जीवित होते हैं; ज्ञानदीप्ति या उज्ज्वल प्रकाश अंधकार के मध्य प्रकट होता है, जहाँ स्वप्न और शाश्वत सत्य एक हो जाते हैं;",

  sa: "पृथिव्याश्च—पारस्परिकसम्बन्धः जीवनं पुनः सजीवयति; वर्षायाः ध्वनिः प्रकृतेः अन्तर्निहितस्पन्दनं प्रकाशयति, तस्याः प्रतिध्वनिश्च मानवचेतसि नूतनानुभवं जनयति; ध्वनेः प्रतिध्वनिः, प्रतिध्वनेः अनुभूतिः, अनुभूतेश्च सृजनशीलता—अनेन निरन्तररूपान्तरणेन प्रकृतिः जीवनं च अविच्छिन्नलये पुनरुज्जीविते भवतः; ज्ञानदीप्तिः उज्ज्वलं वा प्रकाशः अन्धकारस्य मध्ये प्रकाशते, यत्र स्वप्नं शाश्वतं सत्यं च एकीभवतः;",
},

