descShort: {
  en: "The coexistence of open life and nature represents a state where the earth, moon, or body-mind moves like a floating stream,",

  bn: "উন্মুক্ত জীবন-প্রকৃতির সহাবস্থান এমন এক অবস্থার প্রতীক, যেখানে পৃথিবী—চাঁদ বা দেহ-মন এক ভাসমান প্রবাহের মতো, যা আধ্যাত্মিক অনুসন্ধানের ",

  hi: "उन्मुक्त जीवन-प्रकृति का सह-अस्तित्व ऐसी अवस्था का प्रतीक है, जहाँ पृथ्वी—चंद्रमा या देह-मन एक प्रवाहित धारा की भाँति गतिशील होते हैं और आध्यात्मिक",

  sa: "उन्मुक्तजीवन-प्रकृत्योः सहावस्थानं तादृशस्य भावस्य प्रतीकम्, यत्र पृथिवी—चन्द्रः देहमनश्च प्रवहमानधारावत् गतिशीलं भवति, आध्यात्मिकान्वेषणस्य च",
},

title: {
  en: "4) The Coexistence of Open Life and Nature — The Beginning of Natural and Spiritual Life",
  bn: "৪) উন্মুক্ত জীবন-প্রকৃতির সহাবস্থান — প্রাকৃতিক ও আধ্যাত্মিক জীবনের সূচনা",
  hi: "४) उन्मुक्त जीवन-प्रकृति का सह-अस्तित्व — प्राकृतिक और आध्यात्मिक जीवन का आरम्भ",
  sa: "४) उन्मुक्तजीवन-प्रकृत्योः सहावस्थानम् — प्राकृतिकस्य आध्यात्मिकस्य च जीवनस्य आरम्भः",
},

descFull: {
  en: "becoming mutually complementary with spiritual exploration; nature here is refined through purity and becomes an active field for the awakening of consciousness within life and culture; the open sky, earth, light, and subtle vibrations of life lead the human being back toward the depth of their own existence; through this coexistence, earthly experience gradually transforms into spiritual realization, giving birth to a new meaning of life;",

  bn: "পরস্পরের পরিপূরক হয়ে ওঠে; প্রকৃতি এখানে সচ্ছতার সাথে পরিশীলিত হয় এবং জীবনের—সংস্কৃতির অন্তর্গত চেতনা জাগরণের এক সক্রিয় ক্ষেত্র; উন্মুক্ত আকাশ, মাটি, আলো ও জীবনের সূক্ষ্ম স্পন্দন মানুষকে নিজের অস্তিত্বের গভীরে ফিরিয়ে নিয়ে যায়; এই সহাবস্থানের মধ্য দিয়েই পার্থিব অভিজ্ঞতা ধীরে ধীরে আধ্যাত্মিক উপলব্ধিতে রূপান্তরিত হয় এবং জীবনের নতুন অর্থের সূচনা ঘটে;",

  hi: "अन्वेषण के परस्पर पूरक बनते हैं; यहाँ प्रकृति शुद्धता के साथ परिष्कृत होती है और जीवन-संस्कृति के अंतर्गत चेतना-जागरण का एक सक्रिय क्षेत्र बनती है; उन्मुक्त आकाश, मिट्टी, प्रकाश और जीवन के सूक्ष्म स्पंदन मनुष्य को अपने अस्तित्व की गहरাঈ की ओর লৌটাতে হয়; ইসি সহ-অস্তিত্বের মাধ্যমে পার্থিব অভিজ্ঞতা ধীরে ধীরে আধ্যাত্মিক অনুভূতির মধ্যে রূপান্তরিত হয়, এবং জীবনের নতুন অর্থের সৃষ্টি हয়;", 
    
  sa: "परस्परपूरकं भवति; अत्र प्रकृतिः शुद्धतया परिष्कृता भूत्वा जीवनसंस्कृतेः अन्तर्गतं चेतनाजागरणस्य सक्रियं क्षेत्रं भवति; उन्मुक्ताकाशं मृदा प्रकाशश्च जीवनस्य सूक्ष्मस्पन्दनानि च मानवम् स्वस्य अस्तित्वस्य गभीरतां प्रति प्रत्यागन्तुं नयन्ति; अनेन सहावस्थानेन पार्थिवानुभवः शनैः शनैः आध्यात्मिकानुभूतौ रूपान्तरितो भवति, जीवनस्य नूतनार्थस्य च आरम्भो जायते;",
},

