descShort: {
  en: "The clarity of natural life symbolizes the eternal pulse of life-waves, where water, sky, light and the subtle movements of life flow in",

  bn: "প্রাকৃতিক জীবনের স্বচ্ছতা জীবন-তরঙ্গের শাশ্বত স্পন্দনের প্রতীক, যেখানে জল, আকাশ, আলো ও জীবনের সূক্ষ্ম গতি এক অভিন্ন ছন্দে",

  hi: "प्राकृतिक जीवन की पारदर्शिता जीवन-तरंगों के शाश्वत स्पंदन का प्रतीक है, जहाँ जल, आकाश, प्रकाश और जीवन की सूक्ष्म गति एक ही लय में प्रवाहित होती",

  sa: "प्राकृतिकजीवनस्य स्वच्छता जीवनतरङ्गाणां शाश्वतस्पन्दनस्य प्रतीकम् अस्ति, यत्र जलम् आकाशः प्रकाशश्च जीवनस्य सूक्ष्मगतयश्च एकस्मिन् अभिन्नलये प्रवहन्ति;",
},


descFull: {
  en: "a unified rhythm; at the dawn of creation, nature enlivens the fluid womb of the ocean, and the purity of life here is not merely external cleanliness, but a state of perceiving the inner truth of life without any covering; every wave of nature carries the flow of creation and transformation, while every pulse returns toward the deeper unity of life; within this flow, the human being also recognizes its own relationship with nature; thus, life becomes an eternal rhythm, sustaining an uninterrupted pulse of existence even through change;",

  bn: "প্রবাহিত হয়; জীবন সৃষ্টির ঊষালগ্নে প্রকৃতি মহাসাগরের তরল গর্ভকে সজীব করে তোলে, এবং এখানকার জীবনের শ্রেষ্ঠত্ব বা স্বচ্ছতা কেবল বাহ্যিক শুদ্ধতা নয়, বরং তা কোনো আবরণ ছাড়াই জীবনের অন্তরের সত্যকে উপলব্ধি করার এক অবস্থা; প্রকৃতির প্রতিটি তরঙ্গ সৃষ্টি ও পরিবর্তনের ধারাকে বহন করে, আবার প্রতিটি স্পন্দন জীবনের গভীর ঐক্যের দিকে ফিরে যায়; এই প্রবাহে মানবসত্তাও প্রকৃতির সঙ্গে নিজস্ব সম্পর্ক উপলব্ধি করে; ফলে জীবন হয়ে ওঠে শাশ্বত ছন্দ, যেখানে পরিবর্তনের মধ্যেও অস্তিত্বের এক অবিচ্ছিন্ন স্পন্দন বজায় থাকে;",

  hi: "है; सृष्टि के उषाकाल में प्रकृति महासागर की तरल गर्भस्थली को जीवंत करती है, और यहाँ जीवन की श्रेष्ठता या पारदर्शिता केवल बाहरी शुद्धता नहीं, बल्कि बिना किसी आवरण के जीवन के आंतरिक सत्य को अनुभव करने की एक अवस्था है; प्रकृति की प्रत्येक तरंग सृष्टि और परिवर्तन की धारा को वहन करती है, जबकि प्रत्येक स्पंदन जीवन की गहरी एकता की ओर लौटता है; इस प्रवाह में मानवसत्ता भी प्रकृति के साथ अपने संबंध को अनुभव करती है; फलतः जीवन एक शाश्वत लय बन जाता है, जहाँ परिवर्तन के मध्य भी अस्तित्व का एक अविच्छिन्न स्पंदन बना रहता है;",

  sa: "सृष्टेः उषःकाले प्रकृतिः महासागरस्य द्रवगर्भं सजीवयति, अत्र जीवनस्य श्रेष्ठता वा स्वच्छता केवलं बाह्यशुद्धता न, अपि तु आवरणरहिततया जीवनस्य आन्तरिकसत्यस्य अनुभूतेः एकावस्था अस्ति; प्रकृतेः प्रत्येकं तरङ्गं सृष्टेः परिवर्तनस्य च धारां वहति, पुनश्च प्रत्येकं स्पन्दनं जीवनस्य गभीरैक्यस्य दिशि प्रत्यावर्तते; अस्मिन् प्रवाहे मानवसत्तापि प्रकृत्या सह स्वस्य सम्बन्धम् अनुभावयति; अतः जीवनं शाश्वतलयः भवति, यत्र परिवर्तनस्य मध्येऽपि अस्तित्वस्य एकः अविच्छिन्नः स्पन्दनः स्थिरः तिष्ठति;",
},

